    {"claim": "The FAA's delegation of certification to Boeing produced two 737 MAX crashes and 346 deaths because the overseer's discretion got absorbed by the overseen.", "targets": [], "relationship": "supporting-evidence"},
    {"claim": "Capture-resistance is the precondition for risk mitigation, not the tradeoff against it.", "targets": ["safety-vs-bureaucracy-framing"], "relationship": "reframing"},
    {"claim": "Legitimate mandates require pre-committed automatic triggers, statutory funding independence, and personal executive liability at human-machine handoff points.", "targets": [], "relationship": "policy-recommendation"},
